      "id": "nc150-design-twitter",
      "front": "**Design Twitter** · Medium\\n\\n[LeetCode](https://leetcode.com/problems/design-twitter/)\\n\\nDesign a mini social feed: post, follow/unfollow, and fetch the 10 newest posts from yourself and people you follow.\\n\\nPattern? Approach?",
      "back": "**Pattern:** K-way merge with a heap\\n\\n**Key insight:** Store each user's tweets newest-last with a global timestamp; merge followees' lists via a max-heap by time, stopping at 10.\\n\\n**Java**\\n\\n\`\`\`java\\nclass Twitter {\\n    private int time = 0;\\n    private final Map<Integer, List<int[]>> tweets = new HashMap<>();\\n    private final Map<Integer, Set<Integer>> follows = new HashMap<>();\\n    public void postTweet(int userId, int tweetId) {\\n        tweets.computeIfAbsent(userId, x -> new ArrayList<>()).add(new int[]{time++, tweetId});\\n    }\\n    public List<Integer> getNewsFeed(int userId) {\\n        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]); // {time, tweetId, user, idx}\\n        Set<Integer> users = new HashSet<>(follows.getOrDefault(userId, Set.of()));\\n        users.add(userId);\\n        for (int u : users) {\\n            List<int[]> t = tweets.get(u);\\n            if (t != null && !t.isEmpty()) { int i = t.size() - 1; pq.offer(new int[]{t.get(i)[0], t.get(i)[1], u, i}); }\\n        }\\n        List<Integer> feed = new ArrayList<>();\\n        while (!pq.isEmpty() && feed.size() < 10) {\\n            int[] top = pq.poll();\\n            feed.add(top[1]);\\n            int i = top[3] - 1; if (i >= 0) { int[] t = tweets.get(top[2]).get(i); pq.offer(new int[]{t[0], t[1], top[2], i}); }\\n        }\\n        return feed;\\n    }\\n    public void follow(int followerId, int followeeId) {\\n        if (followerId != followeeId) follows.computeIfAbsent(followerId, x -> new HashSet<>()).add(followeeId);\\n    }\\n    public void unfollow(int followerId, int followeeId) {\\n        follows.getOrDefault(followerId, new HashSet<>()).remove(followeeId);\\n    }\\n}\\n\`\`\`\\n\\n**Python**\\n\\n\`\`\`python\\nimport heapq\\nfrom collections import defaultdict\\n\\nclass Twitter:\\n    def __init__(self):\\n        self.time = 0\\n        self.tweets = defaultdict(list)   # user -> [(time, tweetId)]\\n        self.follows = defaultdict(set)\\n\\n    def postTweet(self, user_id: int, tweet_id: int) -> None:\\n        self.tweets[user_id].append((self.time, tweet_id))\\n        self.time += 1\\n\\n    def getNewsFeed(self, user_id: int) -> List[int]:\\n        pq = []  # (-time, tweetId, user, idx)\\n        for u in self.follows[user_id] | {user_id}:\\n            t = self.tweets[u]\\n            if t:\\n                i = len(t) - 1\\n                heapq.heappush(pq, (-t[i][0], t[i][1], u, i))\\n        feed = []\\n        while pq and len(feed) < 10:\\n            _, tid, u, i = heapq.heappop(pq)\\n            feed.append(tid)\\n            if i > 0:\\n                tm, nid = self.tweets[u][i - 1]\\n                heapq.heappush(pq, (-tm, nid, u, i - 1))\\n        return feed\\n\\n    def follow(self, follower_id: int, followee_id: int) -> None:\\n        if follower_id != followee_id:\\n            self.follows[follower_id].add(followee_id)\\n\\n    def unfollow(self, follower_id: int, followee_id: int) -> None:\\n        self.follows[follower_id].discard(followee_id)\\n\`\`\`\\n\\n**Time/Space:** feed O(F + 10 log F) / O(users + tweets)\\n\\n**Pitfall:** Self-follow/unfollow edge cases: a user must always see their own tweets.",
      "deck": "LeetCode::Heap / Priority Queue",
      "tags": [
        "heap",
        "problem",
        "medium",
        "nc150"
      ]
